using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using SportRace.Domain.Entities; using System.Net.Http.Json;
namespace SportRace.Web.Pages.Admin.Results;
public class EditModel:PageModel {private readonly IHttpClientFactory _factory;[BindProperty]public Result Result{get;set;}=new();public EditModel(IHttpClientFactory factory)=>_factory=factory;public async Task<IActionResult> OnGetAsync(int id){var r=await _factory.CreateClient("SportRaceApi1").GetFromJsonAsync<Result>($"api/results/{id}");if(r is null)return NotFound();Result=r;return Page();}public async Task<IActionResult> OnPostAsync(){var r=await _factory.CreateClient("SportRaceApi1").PutAsJsonAsync($"api/results/{Result.Id}",Result);return r.IsSuccessStatusCode?RedirectToPage("Index"):Page();}}
